package com.timetravel.service;
import com.timetravel.engine.*; import com.timetravel.model.*; import java.time.Instant; import java.util.*;
public final class SimulationService {
    private final TimelineEngine timelines=new TimelineEngine();private final ParadoxEngine paradox=new ParadoxEngine();private final ConsequenceEngine consequences=new ConsequenceEngine();private final TimeTravelEngine travel=new TimeTravelEngine(paradox);private SimulationState state;
    public SimulationState start(long seed){state=timelines.create(seed);new AchievementService().update(state);return state;}public SimulationState state(){if(state==null)throw new IllegalStateException("Start or load a simulation first.");return state;}public void load(SimulationState s){state=Objects.requireNonNull(s);new AchievementService().update(state);}
    public Timeline branch(){return timelines.branch(state());}
    public String travel(int year){String result=travel.travel(state(),year);new AchievementService().update(state());return result;}
    public List<Consequence> modify(String eventId,ModificationType type,int amount){Timeline parent=state().current();Event old=parent.event(eventId);if(old==null)throw new IllegalArgumentException("Event not found: "+eventId);int target=old.year();Event revised=switch(type){case PREVENT->old.asPrevented();case DELAY->old.atYear(Math.min(2050,old.year()+Math.max(1,amount)));case ACCELERATE->old.atYear(Math.max(2000,old.year()-Math.max(1,amount)));case INCREASE_IMPACT->old.withImportance(Math.min(10,old.importance()+1));case DECREASE_IMPACT->old.withImportance(Math.max(1,old.importance()-1));case CHANGE_OUTCOME->old.withImportance(Math.max(1,Math.min(10,old.importance()+1)));};if((type==ModificationType.DELAY&&revised.year()==target)||(type==ModificationType.ACCELERATE&&revised.year()==target))throw new IllegalArgumentException("That change would move the event outside the simulation range.");if(target>parent.currentYear())throw new IllegalArgumentException("Travel to the event year before modifying it.");Timeline child=branch();for(int i=0;i<child.events().size();i++)if(child.events().get(i).id().equals(old.id()))child.events().set(i,revised);child.changes().add(new TimelineChange(old.id(),old.title(),type,"Year "+old.year()+" --- "+revised.year()+"; "+type,Instant.now()));List<Consequence> result=consequences.calculate(revised,type);consequences.apply(child,result);int delta=Math.max(4,old.importance()*4);paradox.applyChange(child,delta);state().stats().modified();state().stats().paradoxCreated();state().stats().recordParadox(child.paradox());if(child.paradox()>=90){child.status(TimelineStatus.COLLAPSED);state().stats().collapsed();}new AchievementService().update(state());return result;}
    public boolean stabilize(){Timeline t=state().current();if(t.status()!=TimelineStatus.UNSTABLE&&t.status()!=TimelineStatus.COLLAPSED)return false;if(state().temporalEnergy()<25)return false;state().temporalEnergy(state().temporalEnergy()-25);t.paradox(Math.max(0,t.paradox()-25));t.stability(Math.min(100,t.stability()+30));if(t.paradox()<70)t.status(TimelineStatus.ALTERED);new AchievementService().update(state());return true;}
    public void undoLatest(){Timeline t=state().current();if(t.parentId()==null||t.changes().isEmpty())throw new IllegalStateException("There is no change to undo.");state().currentTimelineId(t.parentId());}
    public ParadoxEngine.Analysis analyze(){return paradox.analyze(state().current(),state().temporalEnergy());}
    public static Map<String,Integer> compare(Timeline a,Timeline b){Map<String,Integer> diffs=new LinkedHashMap<>();Set<String> keys=new LinkedHashSet<>(a.metrics().keySet());keys.addAll(b.metrics().keySet());for(String k:keys)diffs.put(k,b.metrics().getOrDefault(k,0)-a.metrics().getOrDefault(k,0));diffs.put("Stability",(int)Math.round(b.stability()-a.stability()));return diffs;}
}



